// AstroCrawler - which clip plays for which moment, and how loud.
//
// The clips come from two packs with very different levels (the SCI-FI UI SFX
// pack peaks anywhere from -3 dB to -34 dB), so every cue carries its own
// volume: the numbers here are the mix. Generated by Tools > AstroCrawler >
// Gerar SoundLibrary and editable in the inspector afterwards.

using System;
using System.Collections.Generic;

using UnityEngine;

namespace AstroCrawler
{
    [CreateAssetMenu(fileName = "SoundLibrary", menuName = "AstroCrawler/Sound Library")]
    public class SoundLibrary : ScriptableObject
    {
        [Serializable]
        public class Cue
        {
            public Sound sound;
            public AudioClip clip;

            [Tooltip("Optional clip played together with the first, e.g. a tone under an impact.")]
            public AudioClip layer;

            [Range(0f, 1f)] public float volume = 1f;
            [Range(0f, 1f)] public float layerVolume = 1f;

            [Tooltip("Random pitch spread, plus or minus. Keeps a sound that repeats fast from " +
                     "sounding like the same sample on a loop.")]
            [Range(0f, 0.3f)] public float pitchJitter;

            [Tooltip("Minimum seconds between two plays. Five missiles launched in one frame " +
                     "should be one sound, not five stacked.")]
            [Min(0f)] public float cooldown;
        }

        public List<Cue> cues = new List<Cue>();

        [Header("Música")]
        public AudioClip music;
        [Range(0f, 1f)] public float musicVolume = 0.4f;

        [Tooltip("Music under combat is ducked so the feedback sounds stay readable.")]
        [Range(0f, 1f)] public float musicInRunVolume = 0.18f;
    }
}
